<template><div><el-button v-hasPermi="['todo:definition:edit']" type="primary" size="mini" @click="$refs.dialog.show({})">新增触发规则</el-button><el-table :data="rows"><el-table-column prop="event_type" label="事件"/><el-table-column prop="template_name" label="模板"/><el-table-column prop="business_type" label="业务类型"/><el-table-column label="启用"><template slot-scope="scope"><el-switch :value="scope.row.enabled === 'Y'" @change="toggle(scope.row,$event)"/></template></el-table-column><el-table-column label="操作"><template slot-scope="scope"><el-button type="text" @click="$refs.dialog.show(scope.row)">编辑</el-button></template></el-table-column></el-table><trigger-rule-dialog ref="dialog" :templates="templates" :on-save="save"/></div></template>
<script>
import TriggerRuleDialog from './TriggerRuleDialog'
import { saveTriggerRule } from '@/api/todo-definition'
import { field, triggerPayload } from '../resource-contract'
export default { components: { TriggerRuleDialog }, props: { rows: Array, templates: Array, onRefresh: Function }, methods: { async save(data) { await saveTriggerRule(data); await this.onRefresh() }, async toggle(row, enabled) { const json = field(row, 'condition_json', 'conditionJson'); await this.save(triggerPayload({ ...row, enabled, event: { eventType: field(row, 'event_type', 'eventType'), payloadVersion: field(row, 'payload_version', 'payloadVersion') || 1, condition: json ? JSON.parse(json) : {} } })) } } }
</script>
